type DBLoadResult = { db: DB; error: string };
function readDB(): DBLoadResult {
 const loaded=loadLocalData(()=>localStorage,KEY,emptyDB);
 if(loaded.error==='invalid-json')
  return {db:emptyDB,error:'تعذرت قراءة JSON المحفوظ. منع Ledgerly الكتابة فوق البيانات القديمة حتى تنزّل نسخة إنقاذ أو تستعيد نسخة سليمة.'};
 if(loaded.error==='storage-unavailable')
  return {db:emptyDB,error:'تعذر الوصول إلى التخزين المحلي. لن يتم تفعيل الحفظ حتى تستعيد نسخة احتياطية أو يتاح التخزين.'};
 const parsed=loaded.value as Partial<DB>;
 const arrayKeys:(keyof DB)[]=['clients','engagements','risks','workpapers','findings','evidence','trialBalance'];
 const shapeIssue=localDataShapeIssue(parsed,arrayKeys);
 if(shapeIssue==='invalid-root')
  return {db:emptyDB,error:'بنية البيانات المحلية غير صالحة. لم تتم الكتابة فوق المحتوى المحفوظ.'};
 if(shapeIssue==='invalid-collections')
  return {db:emptyDB,error:'إحدى مجموعات البيانات المحلية ليست قائمة صالحة. لم تتم الكتابة فوق المحتوى المحفوظ.'};
 return {db:{...emptyDB,...parsed,
  clients:Array.isArray(parsed.clients)?parsed.clients:[],
  engagements:Array.isArray(parsed.engagements)?parsed.engagements:[],
  risks:Array.isArray(parsed.risks)?parsed.risks:[],
  workpapers:Array.isArray(parsed.workpapers)?parsed.workpapers:[],
  findings:Array.isArray(parsed.findings)?parsed.findings:[],
  evidence:Array.isArray(parsed.evidence)?parsed.evidence:[],
  trialBalance:Array.isArray(parsed.trialBalance)?parsed.trialBalance:[],
  auditLog:Array.isArray(parsed.auditLog)?parsed.auditLog:[],
  completionChecks:parsed.completionChecks&&typeof parsed.completionChecks==='object'&&!Array.isArray(parsed.completionChecks)?parsed.completionChecks:{},
  operations:normalizeAuditOperations(parsed.operations)
 },error:''};
}
function amountValue(v: unknown): number { return parseJodAmount(v) ?? Number.NaN; }
function headerKey(v: unknown): string { return String(v??'').toLowerCase().replace(/[\s_\-./\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه'); }
function download(name: string, content: string, type='application/json') { const blob = new Blob([content], {type}); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href=url; a.download=name; a.click(); URL.revokeObjectURL(url); }
function downloadRecoverySnapshot(db: DB) {
 const content=JSON.stringify(db,null,2);
 download('ledgerly-recovery-current.json',content);
}

function Field({label,value,onChange,placeholder='',type='text'}:{label:string;value:string;onChange:(v:string)=>void;placeholder?:string;type?:string}) { return <label className="audit-field"><span>{label}</span><input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>; }
function SelectField({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:string[]}) { return <label className="audit-field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)}>{options.map(x=>{const parts=x.split('|||'); const val=parts.length>1?parts[0]:x; const label=parts.length>1?parts.slice(1).join('|||'):x; return <option key={x} value={val}>{label}</option>;})}</select></label>; }
function LocalEvidenceAttachment({row,passphrase}:{row:Evidence;passphrase:string}) {
 const [url,setUrl] = useState('');
 const [loadError,setLoadError] = useState('');
 useEffect(()=>{
  let cancelled=false;
  let objectUrl='';
  if(!row.attachmentId)return;
  void getLocalEvidenceFile(row.attachmentId,passphrase).then(file=>{
   if(!file){if(!cancelled)setLoadError('الملف غير موجود في هذا المتصفح');return;}
   objectUrl=URL.createObjectURL(file.blob);
   if(cancelled){URL.revokeObjectURL(objectUrl);return;}
   setUrl(objectUrl);
  }).catch(e=>{if(!cancelled)setLoadError(e instanceof Error?e.message:'تعذر تحميل المرفق.');});
  return ()=>{cancelled=true;if(objectUrl)URL.revokeObjectURL(objectUrl);};
 },[row.attachmentId,passphrase]);
 if(!row.attachmentId||!row.fileName)return <span>—</span>;
 if(loadError)return <span className="table-sub">{loadError}</span>;
 if(!url)return <span className="table-sub">جارٍ تجهيز المرفق…</span>;
 if(row.fileType?.startsWith('image/'))return <a href={url} target="_blank" rel="noreferrer" title={row.fileName} style={{display:'inline-flex',flexDirection:'column',alignItems:'center',gap:'4px',textDecoration:'none'}}><img src={url} alt={row.fileName} loading="lazy" style={{maxWidth:'100px',maxHeight:'72px',objectFit:'contain',borderRadius:'6px',border:'1px solid var(--audit-border,#ddd)',background:'#fff'}}/><span>معاينة الصورة</span></a>;
 return <a href={url} download={row.fileName} className="audit-text-button">تنزيل المرفق</a>;
}
