  const ext=file.name.split('.').pop()?.toLowerCase();
  if(!['csv','txt','xlsx','xls'].includes(ext||'')){setTbError('الصيغة المدعومة لميزان المراجعة هي CSV أو XLSX أو XLS.');return;}
  if(file.size>MAX_IMPORT_FILE_BYTES){setTbError('حجم الملف يتجاوز الحد الآمن (50 ميغابايت).');return;}
