   setDB(p=>({...p,trialBalance:[...p.trialBalance.filter(r=>r.engagementId!==activeEngagement.id),...rows],auditLog:[{id:uid(),at:new Date().toISOString(),action:'استيراد',entity:'ميزان المراجعة',details:`استيراد ${rows.length} حسابًا من ${file.name}؛ فرق الحركة ${imbalance.toFixed(3)}.`,engagementId:activeEngagement.id},...(p.auditLog||[])].slice(0,2000)}));
